def bucketSort(A):
    n = 10
    for i in range(1, n + 1):
        x = get(i)
        b = int(10 * x)          # floor(10*x): half-open bucket for x in [0,1)
        k = 0
        while k < listLen(b) and listGet(b, k) < x:
            k += 1               # scan to the first node >= x
        listInsert(b, k, x)      # keep the bucket sorted

